pub struct BuiltinEntry {
    pub name: &'static str,
    pub category: &'static str,
    pub signature: &'static str,
    pub description: &'static str,
    pub example: &'static str,
}

pub struct PropertyEntry {
    pub name: &'static str,
    pub syntax: &'static str,
    pub description: &'static str,
    pub enables: &'static str,
    pub example: &'static str,
}

pub struct AlgorithmEntry {
    pub name: &'static str,
    pub category: &'static str,
    pub signature: &'static str,
    pub description: &'static str,
    pub preconditions: &'static str,
    pub example: &'static str,
}

pub struct SyntaxRule {
    pub pattern: &'static str,
    pub meaning: &'static str,
    pub example: &'static str,
}

pub struct StdModule {
    pub path: &'static str,
    pub description: &'static str,
    pub provides: &'static str,
}

pub struct ConventionEntry {
    pub field: &'static str,
    pub options: &'static str,
    pub default: &'static str,
    pub description: &'static str,
}

pub struct AssumptionEntry {
    pub name: &'static str,
    pub description: &'static str,
}

fn b(
    name: &'static str,
    category: &'static str,
    signature: &'static str,
    description: &'static str,
    example: &'static str,
) -> BuiltinEntry {
    BuiltinEntry {
        name,
        category,
        signature,
        description,
        example,
    }
}

fn p(
    name: &'static str,
    syntax: &'static str,
    description: &'static str,
    enables: &'static str,
    example: &'static str,
) -> PropertyEntry {
    PropertyEntry {
        name,
        syntax,
        description,
        enables,
        example,
    }
}

fn a(
    name: &'static str,
    category: &'static str,
    signature: &'static str,
    description: &'static str,
    preconditions: &'static str,
    example: &'static str,
) -> AlgorithmEntry {
    AlgorithmEntry {
        name,
        category,
        signature,
        description,
        preconditions,
        example,
    }
}

fn s(pattern: &'static str, meaning: &'static str, example: &'static str) -> SyntaxRule {
    SyntaxRule {
        pattern,
        meaning,
        example,
    }
}

fn m(path: &'static str, description: &'static str, provides: &'static str) -> StdModule {
    StdModule {
        path,
        description,
        provides,
    }
}

fn c(
    field: &'static str,
    options: &'static str,
    default: &'static str,
    description: &'static str,
) -> ConventionEntry {
    ConventionEntry {
        field,
        options,
        default,
        description,
    }
}

fn asm(name: &'static str, description: &'static str) -> AssumptionEntry {
    AssumptionEntry { name, description }
}

